SET SERVEROUTPUT ON;
CREATE TABLE hs_branches(branch_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,branch_name VARCHAR2(120) NOT NULL,city VARCHAR2(80) NOT NULL,address VARCHAR2(250),phone VARCHAR2(25),status VARCHAR2(15) DEFAULT 'ACTIVE');
CREATE TABLE hs_room_types(room_type_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,type_name VARCHAR2(60) UNIQUE NOT NULL,description VARCHAR2(500),base_rate NUMBER(10,2) NOT NULL CHECK(base_rate>=0),capacity NUMBER(2) NOT NULL CHECK(capacity>0));
CREATE TABLE hs_rooms(room_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,branch_id NUMBER NOT NULL REFERENCES hs_branches(branch_id),room_type_id NUMBER NOT NULL REFERENCES hs_room_types(room_type_id),room_number VARCHAR2(12) NOT NULL,floor_no NUMBER(3),status VARCHAR2(20) DEFAULT 'AVAILABLE' CHECK(status IN('AVAILABLE','OCCUPIED','CLEANING','MAINTENANCE','INACTIVE')),CONSTRAINT uq_hs_room UNIQUE(branch_id,room_number));
CREATE TABLE hs_customers(customer_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,full_name VARCHAR2(120) NOT NULL,email VARCHAR2(160) UNIQUE NOT NULL,phone VARCHAR2(25),address VARCHAR2(300),loyalty_tier VARCHAR2(15) DEFAULT 'STANDARD',loyalty_points NUMBER DEFAULT 0,created_at TIMESTAMP DEFAULT SYSTIMESTAMP);
CREATE TABLE hs_employees(employee_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,branch_id NUMBER REFERENCES hs_branches(branch_id),full_name VARCHAR2(120) NOT NULL,job_role VARCHAR2(40) NOT NULL,email VARCHAR2(160) UNIQUE,status VARCHAR2(15) DEFAULT 'ACTIVE');
CREATE TABLE hs_bookings(booking_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,booking_code VARCHAR2(24) UNIQUE NOT NULL,customer_id NUMBER NOT NULL REFERENCES hs_customers(customer_id),room_id NUMBER NOT NULL REFERENCES hs_rooms(room_id),check_in DATE NOT NULL,check_out DATE NOT NULL,adults NUMBER(2) DEFAULT 1 NOT NULL,children NUMBER(2) DEFAULT 0 NOT NULL,nightly_rate NUMBER(10,2) NOT NULL,total_amount NUMBER(12,2) NOT NULL,booking_status VARCHAR2(20) DEFAULT 'CONFIRMED' CHECK(booking_status IN('CONFIRMED','CHECKED_IN','CHECKED_OUT','CANCELLED','NO_SHOW')),created_at TIMESTAMP DEFAULT SYSTIMESTAMP,CONSTRAINT ck_hs_dates CHECK(check_out>check_in));
CREATE TABLE hs_payments(payment_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,booking_id NUMBER NOT NULL REFERENCES hs_bookings(booking_id),amount NUMBER(12,2) NOT NULL CHECK(amount>0),payment_method VARCHAR2(20) NOT NULL CHECK(payment_method IN('CASH','CARD','UPI','BANK_TRANSFER')),reference_no VARCHAR2(80),payment_status VARCHAR2(15) DEFAULT 'SUCCESS',paid_at TIMESTAMP DEFAULT SYSTIMESTAMP);
CREATE TABLE hs_housekeeping_tasks(task_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,room_id NUMBER NOT NULL REFERENCES hs_rooms(room_id),assigned_to NUMBER REFERENCES hs_employees(employee_id),task_type VARCHAR2(30) DEFAULT 'CLEANING',priority VARCHAR2(12) DEFAULT 'NORMAL',task_status VARCHAR2(15) DEFAULT 'PENDING',due_at TIMESTAMP,completed_at TIMESTAMP,remarks VARCHAR2(500));
CREATE TABLE hs_maintenance_requests(request_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,room_id NUMBER NOT NULL REFERENCES hs_rooms(room_id),reported_by NUMBER REFERENCES hs_employees(employee_id),issue_title VARCHAR2(150) NOT NULL,issue_details VARCHAR2(1000),priority VARCHAR2(12) DEFAULT 'NORMAL',request_status VARCHAR2(15) DEFAULT 'OPEN',reported_at TIMESTAMP DEFAULT SYSTIMESTAMP,resolved_at TIMESTAMP);
CREATE TABLE hs_audit_log(audit_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,entity_name VARCHAR2(50) NOT NULL,entity_id NUMBER,action_name VARCHAR2(30) NOT NULL,action_by VARCHAR2(100) DEFAULT USER,action_at TIMESTAMP DEFAULT SYSTIMESTAMP,details VARCHAR2(1000));
CREATE INDEX ix_hs_booking_room_dates ON hs_bookings(room_id,check_in,check_out);
CREATE INDEX ix_hs_booking_customer ON hs_bookings(customer_id);
CREATE INDEX ix_hs_payment_booking ON hs_payments(booking_id);
CREATE OR REPLACE VIEW hs_v_booking_details AS SELECT b.booking_id,b.booking_code,c.full_name customer_name,c.email,r.room_number,rt.type_name room_type,br.branch_name,b.check_in,b.check_out,b.adults,b.children,b.nightly_rate,b.total_amount,b.booking_status,b.created_at FROM hs_bookings b JOIN hs_customers c ON c.customer_id=b.customer_id JOIN hs_rooms r ON r.room_id=b.room_id JOIN hs_room_types rt ON rt.room_type_id=r.room_type_id JOIN hs_branches br ON br.branch_id=r.branch_id;
CREATE OR REPLACE VIEW hs_v_payment_summary AS SELECT b.booking_id,b.booking_code,b.total_amount,NVL(SUM(CASE WHEN p.payment_status='SUCCESS' THEN p.amount ELSE 0 END),0) paid_amount,b.total_amount-NVL(SUM(CASE WHEN p.payment_status='SUCCESS' THEN p.amount ELSE 0 END),0) due_amount FROM hs_bookings b LEFT JOIN hs_payments p ON p.booking_id=b.booking_id GROUP BY b.booking_id,b.booking_code,b.total_amount;
